-- Requires MySQL 8.0.16 or later (CHECK constraints are enforced from there). Verified on MySQL 8.4 LTS.
-- Load it into an EMPTY database with the mysql client; the script stops at the first error:
--   mysql --default-character-set=utf8mb4 --skip-commands --skip-system-command --database <name> < <file>.sql
-- (--skip-commands needs mysql 8.4.6 or later; without it the client still reads this file as plain statements,
-- because no data in it can start a line.) Do not load it with the "source" command of an untrusted file.
-- A blob is written in hex, twice its size: one value over about 8 MB is more than the client's default max_allowed_packet of 16 MB; add --max-allowed-packet=1G.
-- MySQL commits DDL, so a failed load is not rolled back: drop the database or the tables listed below and load again.
-- The first statement creates the table _demodb_import and fails when it exists; the last one fills it: a row there means the load completed.
-- DROP TABLE _demodb_import removes the marker once you no longer need it.
-- Text comparison in MySQL is case- and accent-insensitive by default, unlike SQLite's exact comparison: keys that differ only by case or accents in SQLite are duplicates here and stop the load.
-- The export warns about the key values it finds that collide that way (key-values-collide); it cannot find every kind of collision MySQL's collation makes.
-- Tables (11): authors, publishers, titles, titleauthor, stores, sales, roysched, discounts, jobs, pub_info, employee
--
-- 3 thing(s) are not carried exactly:
-- [values-normalized] discounts.discount: 2 REAL and 1 INTEGER value(s) share one DECIMAL(4,2) column: SQLite keeps them apart (5 and 5.0), DECIMAL(4,2) does not; each REAL is written as the exact decimal of its shortest spelling, for example 10.5
-- [values-normalized] titles.price: 14 REAL and 2 INTEGER value(s) share one DECIMAL(4,2) column: SQLite keeps them apart (5 and 5.0), DECIMAL(4,2) does not; each REAL is written as the exact decimal of its shortest spelling, for example 19.99
-- [view-not-carried] titleview: views are written in the SQL dialect of their engine and are not translated across engines

SET NAMES utf8mb4;
SET SESSION sql_mode = 'STRICT_ALL_TABLES,NO_AUTO_VALUE_ON_ZERO,NO_ENGINE_SUBSTITUTION,NO_ZERO_DATE,NO_ZERO_IN_DATE';
CREATE TABLE `_demodb_import` (`dataset` VARCHAR(255) NOT NULL, `edition` VARCHAR(255) NOT NULL, `source_sha256` CHAR(64) NOT NULL, `datatug_version` VARCHAR(64) NOT NULL, `tables_count` INT NOT NULL, `rows_count` BIGINT NOT NULL, PRIMARY KEY (`dataset`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `authors` (
  `au_id` VARCHAR(11) NOT NULL,
  `au_lname` VARCHAR(40) NOT NULL,
  `au_fname` VARCHAR(20) NOT NULL,
  `phone` VARCHAR(12) NOT NULL DEFAULT 'UNKNOWN',
  `address` VARCHAR(40),
  `city` VARCHAR(20),
  `state` VARCHAR(2),
  `zip` VARCHAR(5),
  `contract` BIGINT NOT NULL,
  PRIMARY KEY (`au_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `publishers` (
  `pub_id` VARCHAR(4) NOT NULL,
  `pub_name` VARCHAR(40),
  `city` VARCHAR(20),
  `state` VARCHAR(2),
  `country` VARCHAR(30) DEFAULT 'USA',
  PRIMARY KEY (`pub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `titles` (
  `title_id` VARCHAR(6) NOT NULL,
  `title` VARCHAR(80) NOT NULL,
  `type` VARCHAR(12) NOT NULL DEFAULT 'UNDECIDED',
  `pub_id` VARCHAR(4),
  `price` DECIMAL(4,2),
  `advance` DECIMAL(5,0),
  `royalty` BIGINT,
  `ytd_sales` BIGINT,
  `notes` VARCHAR(200),
  `pubdate` TEXT NOT NULL DEFAULT ('2000-01-01'),
  PRIMARY KEY (`title_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `titleauthor` (
  `au_id` VARCHAR(11) NOT NULL,
  `title_id` VARCHAR(6) NOT NULL,
  `au_ord` BIGINT,
  `royaltyper` BIGINT,
  PRIMARY KEY (`au_id`, `title_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `stores` (
  `stor_id` VARCHAR(4) NOT NULL,
  `stor_name` VARCHAR(40),
  `stor_address` VARCHAR(40),
  `city` VARCHAR(20),
  `state` VARCHAR(2),
  `zip` VARCHAR(5),
  PRIMARY KEY (`stor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `sales` (
  `stor_id` VARCHAR(4) NOT NULL,
  `ord_num` VARCHAR(20) NOT NULL,
  `ord_date` TEXT NOT NULL,
  `qty` BIGINT NOT NULL,
  `payterms` VARCHAR(12) NOT NULL,
  `title_id` VARCHAR(6) NOT NULL,
  PRIMARY KEY (`stor_id`, `ord_num`, `title_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `roysched` (
  `title_id` VARCHAR(6),
  `lorange` BIGINT,
  `hirange` BIGINT,
  `royalty` BIGINT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `discounts` (
  `discounttype` VARCHAR(40) NOT NULL,
  `stor_id` VARCHAR(4),
  `lowqty` BIGINT,
  `highqty` BIGINT,
  `discount` DECIMAL(4,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `jobs` (
  `job_id` BIGINT NOT NULL AUTO_INCREMENT,
  `job_desc` VARCHAR(50) NOT NULL DEFAULT 'New Position - title not formalized yet',
  `min_lvl` BIGINT NOT NULL,
  `max_lvl` BIGINT NOT NULL,
  PRIMARY KEY (`job_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `pub_info` (
  `pub_id` VARCHAR(4) NOT NULL,
  `logo` BLOB,
  `pr_info` TEXT,
  PRIMARY KEY (`pub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `employee` (
  `emp_id` VARCHAR(10) NOT NULL,
  `fname` VARCHAR(20) NOT NULL,
  `minit` VARCHAR(1),
  `lname` VARCHAR(30) NOT NULL,
  `job_id` BIGINT NOT NULL DEFAULT 1,
  `job_lvl` BIGINT DEFAULT 10,
  `pub_id` VARCHAR(4) NOT NULL DEFAULT '9952',
  `hire_date` TEXT NOT NULL DEFAULT ('2000-01-01'),
  PRIMARY KEY (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
START TRANSACTION;
COMMIT;
CREATE INDEX `authors_aunmind` ON `authors` (`au_lname`, `au_fname`);
CREATE INDEX `titles_titleind` ON `titles` (`title`);
CREATE INDEX `titleauthor_auidind` ON `titleauthor` (`au_id`);
CREATE INDEX `titleauthor_titleidind` ON `titleauthor` (`title_id`);
CREATE INDEX `sales_titleidind` ON `sales` (`title_id`);
CREATE INDEX `roysched_titleidind` ON `roysched` (`title_id`);
CREATE INDEX `employee_employee_ind` ON `employee` (`lname`, `fname`, `minit`);
ALTER TABLE `authors` ADD CHECK (REGEXP_LIKE(`au_id`, '^[0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9][0-9][0-9]$', 'cn'));
ALTER TABLE `authors` ADD CHECK (REGEXP_LIKE(`zip`, '^[0-9][0-9][0-9][0-9][0-9]$', 'cn'));
ALTER TABLE `publishers` ADD CHECK (`pub_id` COLLATE utf8mb4_bin IN ( '1389' , '0736' , '0877' , '1622' , '1756' ) OR REGEXP_LIKE(`pub_id`, '^99[0-9][0-9]$', 'cn'));
ALTER TABLE `jobs` ADD CHECK (`min_lvl` >= 10);
ALTER TABLE `jobs` ADD CHECK (`max_lvl` <= 250);
ALTER TABLE `employee` ADD CHECK (REGEXP_LIKE(`emp_id`, '^[A-Z][A-Z][A-Z][1-9][0-9][0-9][0-9][0-9][FM]$', 'cn') OR REGEXP_LIKE(`emp_id`, '^[A-Z]-[A-Z][1-9][0-9][0-9][0-9][0-9][FM]$', 'cn'));
ALTER TABLE `titles` ADD FOREIGN KEY (`pub_id`) REFERENCES `publishers` (`pub_id`);
ALTER TABLE `titleauthor` ADD FOREIGN KEY (`title_id`) REFERENCES `titles` (`title_id`);
ALTER TABLE `titleauthor` ADD FOREIGN KEY (`au_id`) REFERENCES `authors` (`au_id`);
ALTER TABLE `sales` ADD FOREIGN KEY (`title_id`) REFERENCES `titles` (`title_id`);
ALTER TABLE `sales` ADD FOREIGN KEY (`stor_id`) REFERENCES `stores` (`stor_id`);
ALTER TABLE `roysched` ADD FOREIGN KEY (`title_id`) REFERENCES `titles` (`title_id`);
ALTER TABLE `discounts` ADD FOREIGN KEY (`stor_id`) REFERENCES `stores` (`stor_id`);
ALTER TABLE `pub_info` ADD FOREIGN KEY (`pub_id`) REFERENCES `publishers` (`pub_id`);
ALTER TABLE `employee` ADD FOREIGN KEY (`pub_id`) REFERENCES `publishers` (`pub_id`);
ALTER TABLE `employee` ADD FOREIGN KEY (`job_id`) REFERENCES `jobs` (`job_id`);
-- end of script
